// Deduplication and Minimal Notification Sanitization
// Non-negotiable Rule: ZERO salary, ZERO receipt images, ZERO sensitive attendance details
const input = $input.first().json.body || $input.first().json;

const employeeId = input.employee_id || 'UNKNOWN';
const period = input.period || 'current month';
const actionableCount = input.actionable_count || 1;

// Generate deduplication fingerprint: hash of employee + period + count
const crypto = require('crypto');
const dedupFingerprint = crypto.createHash('md5').update(`${employeeId}_${period}_${actionableCount}`).digest('hex');

// Minimal, privacy-safe message template per Spec Section 6
const safeMessage = `Your ${period} self-audit has ${actionableCount} item(s) requiring attention. Sign in to the HR portal to review the evidence and next steps.`;
const portalUrl = `https://portal.company.com/audit?period=${period}`;

return [{
  json: {
    employee_id: employeeId,
    period: period,
    actionable_count: actionableCount,
    dedup_fingerprint: dedupFingerprint,
    message_body: safeMessage,
    portal_url: portalUrl,
    dispatched_at: new Date().toISOString()
  }
}];

